{"content": """"Referee test harness.

Sources of truth for f:
  (a) `./solver` grid (validated oracle)
  (b) scratch/indep.py Rec (independent re-derivation of MISSION s2 recurrence)

Implements the CLAIM's definitions literally:
  B_c(x)  = f(c+x,c)-(c+x) if f(c+x,c) >= c+x else undefined
  V''(a)  = U_{c<r} {B_c(a+r-c)} (defined only)
  V'(a)   = (U_{c<r} {B_c(0)-(r-c)-a}) intersect Z_{>=0}
  m_r     = 1 + max of all defined B_c(x), c<r
  H_0 = V'(0); k_a = mex_{>=0}(V''(a) u H_a); H_{a+1} = dec(H_a) u {k_a-1}
and compares k_a against B_r(a).
"""

import subprocess


def load_grid(rmax, qmax):
    out = subprocess.run(["./solver", "table", "--rmax", str(rmax), "--qmax", str(qmax)],
                         capture_output=True, text=True).stdout.strip().split("\n")
    G = []
    for line in out:
        G.append([int(t) for t in line.split()])
    assert len(G) == qmax + 1, (len(G), qmax)
    return G


def Bval(G, c, x):
    """B_c(x) per the claim, or None if undefined. G[q][c] = f(q,c) for c<=q;
    for c>q the solver prints f(q,q), so we must only call with c<=q=c+x (x>=0)."""
    q = c + x
    v = G[q][c]
    if v >= q:
        return v - q
    return None


def mex(S):
    m = 0
    while m in S:
        m += 1
    return m


def dec(H):
    return {h - 1 for h in H if h >= 1}


def run_machine(G, r, amax):
    """Return lists k[0..], H[0..] per the claim; stop at first k==0."""
    # m_r = 1 + max all defined B_c(x), c<r.  We scan a generous x-range and
    # also verify saturation (i.e. that the max over the scanned range is stable).
    X = amax + r + 5
    mvals = []
    for c in range(r):
        for x in range(X + 1):
            b = Bval(G, c, x)
            if b is not None:
                mvals.append(b)
    m_r = 1 + max(mvals)

    H = set()
    for c in range(r):
        b = Bval(G, c, 0)
        if b is None:
            continue
        v = b - (r - c)
        if v >= 0:
            H.add(v)
    H0 = set(H)
    ks = []
    Hs = [H0]
    for a in range(amax + 1):
        Vs = set()
        for c in range(r):
            b = Bval(G, c, a + r - c)
            if b is not None:
                Vs.add(b)
        k = mex(Vs | H)
        ks.append(k)
        if k == 0:
            return ks, Hs, m_r, True
        H = dec(H) | {k - 1}
        Hs.append(H)
    return ks, Hs, m_r, False
