{"content": """"Referee test harness (v2). f taken from ./solver grid; machine implemented
literally from the CLAIM text."""

import subprocess


def load_grid(rmax, qmax):
    out = subprocess.run(["./solver", "table", "--rmax", str(rmax), "--qmax", str(qmax)],
                         capture_output=True, text=True).stdout.strip().split("\n")
    G = []
    for line in out:
        G.append([int(t) for t in line.split()])
    assert len(G) == qmax + 1, (len(G), qmax)
    return G


def Bval(G, c, x):
    q = c + x
    if q >= len(G):
        return None  # out of range, distinct from 'undefined'
    v = G[q][c]
    if v >= q:
        return v - q
    return "UNDEF"


class Bs:
    """B_c(x) lookup with a defined/undefined/out-of-range distinction."""

    def __init__(self, G, C):
        self.G = G
        self.C = C

    def get(self, c, x):
        if c > self.C:
            raise ValueError("c out of range")
        if x < 0:
            raise ValueError("x<0")
        q = c + x
        if q >= len(self.G):
            return None
        v = self.G[q][c]
        return (v - q) if v >= q else "UNDEF"


def mex(S):
    m = 0
    while m in S:
        m += 1
    return m


def dec(H):
    return {h - 1 for h in H if h >= 1}


def run_machine(bs, r, amax, m_r):
    """Literal implementation of the claim's machine. Returns k list, H list,
    stop flag."""
    H = set()
    for c in range(r):
        b = bs.get(c, 0)
        if b is None:
            raise ValueError("out of range in V'(0)")
        if b == "UNDEF":
            continue
        v = b - (r - c)
        if v >= 0:
            H.add(v)
    Hs = [set(H)]
    ks = []
    for a in range(amax + 1):
        Vs = set()
        for c in range(r):
            b = bs.get(c, a + r - c)
            if b is None:
                raise ValueError("out of range in V''(%d)" % a)
            if b == "UNDEF":
                continue
            Vs.add(b)
        k = mex(Vs | H)
        ks.append(k)
        if k == 0:
            return ks, Hs, True
        H = dec(H) | {k - 1}
        Hs.append(set(H))
    return ks, Hs, False


def max_defined_B(bs, r, x_max):
    """1 + max over all defined B_c(x), c<r, 0<=x<=x_max."""
    vals = []
    for c in range(r):
        for x in range(x_max - c + 1):
            b = bs.get(c, x)
            if b is None:
                continue
            if b != "UNDEF":
                vals.append(b)
    return 1 + max(vals)
