        census[int(t[0])] = dict(cls=t[1], period=int(t[2]), N=int(t[3]),
                                 dvals=t[4], deathq=t[5], dconst=t[6])

def row_data(c):
    """returns (cls, N, p, u) per the claim's conventions, computed from B_c."""
